import numpy as np

def idx(r, c, ch):
    return (r * 10 + c) * 5 + ch

states = []

def make(name, agent=None, prev=None, wall=False, moving=None, reward=None):
    x = np.zeros(500)
    if wall:
        for r in range(10):
            for c in range(10):
                if r == 0 or r == 9 or c == 0 or c == 9:
                    x[idx(r, c, 3)] = 1
    if agent:
        x[idx(agent[0], agent[1], 0)] = 1
    if moving:
        x[idx(moving[0], moving[1], 1)] = 1
    if reward:
        x[idx(reward[0], reward[1], 2)] = 1
    if prev:
        x[idx(prev[0], prev[1], 4)] = 1
    states.append((name, x))

