import numpy as np

def make_input(agent=None, mov=None, wall=True):
    X = np.zeros(500)
    if agent is not None:
        r, c = agent
        X[(r * 10 + c) * 5 + 0] = 1
    if mov is not None:
        r, c = mov
        X[(r * 10 + c) * 5 + 1] = 1
    if wall:
        for r in range(10):
            for c in range(10):
                if r == 0 or r == 9 or c == 0 or c == 9:
                    X[(r * 10 + c) * 5 + 3] = 1
    return X

states = []
positions = []
for r in range(1, 9):
    for c in range(1, 9):
        agent = (r, c)
        mov = (r - 1, c) if r > 1 else None
        X = make_input(agent=agent, mov=mov, wall=True)
        states.append(X)
        positions.append((r, c, mov))

X = np.array(states)
