import numpy as np

def make_obs(agent=None, moving=None, reward=None, obstacle=None, prev=None, wall=True):
    obs = np.zeros((10,10,5), dtype=float)
    if wall:
        for r in range(10):
            for c in range(10):
                if r in (0,9) or c in (0,9):
                    obs[r,c,3] = 1.0
    if agent is not None:
        obs[agent[0], agent[1], 0] = 1.0
    if moving is not None:
        for m in moving:
            obs[m[0], m[1], 1] = 1.0
    if reward is not None:
        for rw in reward:
            obs[rw[0], rw[1], 2] = 1.0
    if obstacle is not None:
        for ob in obstacle:
            obs[ob[0], ob[1], 3] = 1.0
    if prev is not None:
        for p in prev:
            obs[p[0], p[1], 4] = 1.0
    return obs.reshape(-1)

cases = {
  'base':      dict(agent=(5,4)),
  'mov_left':  dict(agent=(5,4), moving=[(5,3)]),
  'mov_right': dict(agent=(5,4), moving=[(5,5)]),
  'mov_above': dict(agent=(5,4), moving=[(4,4)]),
  'mov_below': dict(agent=(5,4), moving=[(6,4)]),
  'obs_above': dict(agent=(5,4), obstacle=[(4,4)]),
  'obs_left':  dict(agent=(5,4), obstacle=[(5,3)]),
}
names = list(cases.keys())
X = np.stack([make_obs(**cases[n]) for n in names])
out = forward(X)
base = out[0]
print("action order: 0=noop 1=up 2=down 3=left 4=right")
for i, n in enumerate(names):
    lg = out[i]
    d = lg - base
