          f"logits=[{lg[0]:6.2f} {lg[1]:6.2f} {lg[2]:6.2f} {lg[3]:6.2f} {lg[4]:6.2f}]  "
          f"d=[{d[0]:5.2f} {d[1]:5.2f} {d[2]:5.2f} {d[3]:5.2f} {d[4]:5.2f}]")
